import {
    Table,
    GenericColumn,
    ReferenceColumn,
    TableNameColumn,
    StringColumn,
    GuidColumn,
    ListColumn,
} from '@servicenow/sdk/core'

export const sysevent_email_template = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    audit: true,
    display: 'name',
    extends: 'sys_metadata',
    label: 'Email Template',
    name: 'sysevent_email_template',
    schema: {
        sms_alternate: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'SMS alternate',
            maxLength: 8000,
        }),
        email_layout: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Email layout',
            referenceTable: 'sys_email_layout',
        }),
        message: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'Message',
            maxLength: 4000,
        }),
        collection: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            default: 'incident',
            label: 'Table',
        }),
        subject: StringColumn({
            label: 'Subject',
            maxLength: 100,
        }),
        message_text: GenericColumn({
            columnType: 'email_script',
            dependent: 'collection',
            label: 'Message text',
            maxLength: 4000,
        }),
        name: StringColumn({
            label: 'Name',
            mandatory: true,
        }),
        sys_version: StringColumn({
            default: '2',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Notification Version',
                    label: 'Sys version',
                    plural: 'Sys versions',
                    language: 'en',
                },
            ],
        }),
        message_html: GenericColumn({
            attributes: {
                convert_urls: false,
            },
            columnType: 'html_script',
            dependent: 'collection',
            label: 'Message HTML',
            maxLength: 4000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        message_list: ListColumn({
            attributes: {
                array: 'denormalized',
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Push Messages',
            maxLength: 1024,
            referenceTable: 'sys_push_notif_msg',
        }),
    },
    textIndex: true,
})
